// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz params: deposit amount and attacker as the caller address
    function testFuzz_property(uint96 depositAmount, address attackerAddr) public {
        // keep depositAmount within reasonable bounds and non-zero
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));
        // avoid the zero address for actor
        vm.assume(attackerAddr != address(0));

        // deploy attacker helper controlled by attackerAddr externally
        // we deploy our Attacker contract and set it up to target c
        attacker = new Attacker(address(c));

        // fund the attacker externally so it can deposit and trigger withdraw
        vm.deal(address(attacker), depositAmount);

        // have attacker deposit into c
        attacker.deposit{value: depositAmount}();

        // Now attacker will call withdrawAll which in the mutant reentrantly
        // can cause credit to remain non-zero after completion. We invoke
        // withdrawAll via the attacker contract so its fallback/receive can
        // reenter if the external call happens before zeroing.
        bool ok;
        try attacker.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after withdrawAll completes, the recorded credit for the caller must be zero.
        // We read c.credit(attacker) via the auto getter; this should be zero for the correct contract
        // for all inputs, and the mutant (external call before zeroing) can leave it > 0 for some inputs.
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

// Minimal adversarial helper that reenters on receive to exploit withdraw-before-zero bug.
contract Attacker {
    C public target;
    bool public reentered;

    constructor(address _target) {
        target = C(_target);
        reentered = false;
    }

    // deposit into target; called by test with value
    function deposit() external payable {
        // call target.deposit with the same msg.value
        (bool ok, ) = address(target).call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // trigger withdrawAll from this contract
    function triggerWithdraw() external {
        // call target.withdrawAll as this contract
        target.withdrawAll();
    }

    // receive will be invoked when target sends funds; perform reentrancy once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // reenter withdrawAll while original withdraw is in-flight in mutant
            // ignore errors to let outer flow continue
            try target.withdrawAll() {
            } catch {
            }
        }
    }
}

