pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: deposit amount and an arbitrary seed for attacker behavior
    function testFuzz_property(uint256 depositAmount, uint256 seed) public {
        // keep depositAmount within reasonable ETH bounds
        depositAmount = bound(depositAmount, 1 wei, 1 ether);

        // deploy an attacker that will reenter on receive
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can deposit
        vm.deal(address(attacker), depositAmount);

        // attacker deposits into c to acquire credit
        attacker.deposit{value: depositAmount}();

        // Now attempt to withdrawAll via attacker which will reenter when receiving funds
        // The seed controls whether attacker will try to reenter (nonzero => reenter once)
        bool willReenter = (seed % 2 == 1);
        attacker.setReenter(willReenter);

        // perform the withdrawal; attacker will call c.withdrawAll which may trigger reentrancy
        attacker.triggerWithdrawAll();

        // General fact: in the correct contract, after withdrawAll completes, the attacker's recorded credit is zero.
        // This will be true for all inputs on the reference implementation and will be violated by the mutant for some inputs.
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

// Minimal attacker that can reenter during receive
contract Attacker {
    address immutable target;
    bool reenter;

    constructor(address _target) payable {
        target = _target;
    }

    receive() external payable {
        if (reenter) {
            reenter = false; // only reenter once to avoid infinite loop
            // reenter by calling withdrawAll again
            C(target).withdrawAll();
        }
    }

    function setReenter(bool r) public {
        reenter = r;
    }

    function deposit() public payable {
        // deposit into target to gain credit
        C(target).deposit{value: msg.value}();
    }

    function triggerWithdrawAll() public {
        C(target).withdrawAll();
    }
}

