pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and a boolean deciding whether attacker should try reentrancy
    function testFuzz_property(uint128 amount, bool attackerReenters) public {
        // keep amount within reasonable bounds and nonzero to be meaningful
        uint256 amt = bound(uint256(amount), 1, 1e18);

        // deploy an attacker contract that can reenter when receiving ETH
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can deposit
        vm.deal(address(attacker), amt);

        // attacker deposits into c to get credit
        attacker.deposit{value: amt}();

        // if attackerReenters is true, configure attacker to reenter on receive
        attacker.setReenter(attackerReenters);

        // now invoke withdrawAll from attacker; we observe c's stored credit for attacker after completion
        // note: withdrawAll is called by attacker via its triggerWithdraw which does a vm.prank-like external call
        attacker.triggerWithdraw();

        // The universal property we assert: after withdrawAll completes, recorded credit for attacker must be zero
        // We read c's public getter for the mapping (credit is a private in original but per problem statement
        // the test must observe via public surface. To comply with provided constraints, assume C exposes
        // a public getter named credit (the original reference had mapping credit accessible in test intent).
        // If the mapping is not public, tests should instead read address(c).balance; however the property
        // we need is the depositor's recorded credit equals zero. We'll attempt to call c.credit(attacker)
        // as required by the problem statement.

        // Single assertion: reference contract keeps credit zero for all inputs; mutant can leave it non-zero
        assertTrue(c.credit(address(attacker)) == 0);
    }
}

// Minimal attacker helper that can reenter C during its receive()
contract Attacker {
    C c;
    bool reenter;

    constructor(address _c) {
        c = C(_c);
    }

    function setReenter(bool v) external { reenter = v; }

    // deposit into C
    function deposit() external payable {
        // call C.deposit as this contract
        c.deposit{value: msg.value}();
    }

    // Trigger withdrawAll from this contract
    function triggerWithdraw() external {
        c.withdrawAll();
    }

    // when receiving ether, optionally reenter and call withdrawAll again
    receive() external payable {
        if (reenter) {
            // reenter withdrawAll during the external call
            c.withdrawAll();
        }
    }
}

