pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: deposit amount and attacker initial funding
    function testFuzz_property(uint256 depositAmount, uint256 attackerFund) public {
        // keep amounts in reasonable ranges but still wide
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerFund = bound(attackerFund, 0, 2 ether);

        // deploy attacker who will reenter on receive to exploit mutant ordering
        Attacker attacker = new Attacker(address(c));

        // fund attacker and the contract depositor (attacker will be the depositor)
        vm.deal(address(attacker), attackerFund + depositAmount);

        // attacker deposits into C
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // record contract balance according to blockchain before withdraw
        uint256 beforeReal = address(c).balance;

        // perform withdrawAll from attacker which on mutant can reenter
        vm.prank(address(attacker));
        // attacker will reenter during the low-level call if mutant present
        try c.withdrawAll() {
            // ok
        } catch {
            // if mutant causes revert via reentrancy or other, still continue
        }

        // After withdrawAll in the correct contract, the blockchain balance of c should equal
        // the contract's internal accounting (tracked by its public getter if available).
        // The reference C keeps an internal `balance` variable but it is not public in the source
        // we have; however the observable universal invariant we can rely on is that the contract's
        // on-chain ETH balance must equal the amount its logic tracked and updated when withdraws
        // succeed. For the correct implementation (no reentrancy), after withdrawAll completes the
        // contract's actual balance is either unchanged or decreased exactly by the withdrawn amount
        // matching its accounting. The mutant can leave funds in contract or mismatch by reentering.

        // We assert a relation that must hold for the reference: the contract's real balance is <= beforeReal
        // and also equals its internal accounting as seen by observing deposits minus successful sends.
        // Since we cannot read a private internal variable, we assert a weaker universal fact that holds
        // for the correct contract for all inputs: address(c).balance <= beforeReal.
        // The mutant that reenters and causes inconsistent sends can lead to address(c).balance > beforeReal
        // (because reentrant deposit during withdraw could increase balance observed after completion).

        // Single assertion observing c's public state (address(c).balance)
        assertTrue(address(c).balance <= beforeReal);
    }
}

// Minimal attacker that reenters on receive to exploit mutant ordering
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _t) {
        target = _t;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt reentrant withdraw; if target is the mutant this will reenter during external call
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore result
            ok;
        }
    }
}

