pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor address and amount to deposit (must be >0 and within balanceable bounds)
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount within reasonable bounds (but wide)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund depositor and perform deposit
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // record contract's external ETH balance before withdraw
        uint256 beforeAddrBalance = address(c).balance;

        // depositor withdraws all
        vm.prank(depositor);
        c.withdrawAll();

        // After withdrawAll, the contract's external ETH balance must have decreased by exactly amount
        // This holds in the reference implementation because it decrements the internal and transfers out
        // The mutant that removed balance -= oCredit will leave address(c).balance larger than expected
        assertTrue(address(c).balance + amount == beforeAddrBalance, "contract balance did not decrease by withdrawn amount");
    }
}

